import{_ as t,o as e,c as n,ag as i}from"./chunks/framework.Dx86EdC1.js";const h=JSON.parse('{"title":"Menu & Tema Publik","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/menu-tema.md","filePath":"panduan-pengguna/menu-tema.md","lastUpdated":1791382762000}'),d={name:"panduan-pengguna/menu-tema.md"};function r(o,a,l,s,u,m){return e(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="menu-tema-publik" tabindex="-1">Menu &amp; Tema Publik <a class="header-anchor" href="#menu-tema-publik" aria-label="Permalink to &quot;Menu &amp; Tema Publik&quot;">​</a></h1><h2 id="menu-navigasi" tabindex="-1">Menu Navigasi <a class="header-anchor" href="#menu-navigasi" aria-label="Permalink to &quot;Menu Navigasi&quot;">​</a></h2><p>Kelola di <strong>CMS Portal → Menu</strong> (<code>/admin/menus</code>).</p><table tabindex="0"><thead><tr><th>Kolom</th><th>Keterangan</th></tr></thead><tbody><tr><td>Label</td><td>Teks menu</td></tr><tr><td>Tautan</td><td>URL eksternal atau pilih halaman statis</td></tr><tr><td>Induk (parent)</td><td>Membuat submenu/dropdown bertingkat</td></tr><tr><td>Urutan</td><td><code>sort_order</code> menentukan posisi</td></tr><tr><td>Aktif</td><td>Menu nonaktif tidak tampil</td></tr></tbody></table><p>Perubahan langsung terlihat di header seluruh halaman portal.</p><h2 id="mengganti-tema" tabindex="-1">Mengganti Tema <a class="header-anchor" href="#mengganti-tema" aria-label="Permalink to &quot;Mengganti Tema&quot;">​</a></h2><p>Kelola di <strong>CMS Portal → Tema</strong> (<code>/admin/themes</code>).</p><p>Tema bawaan:</p><table tabindex="0"><thead><tr><th>Tema</th><th>Keterangan</th></tr></thead><tbody><tr><td><code>default</code></td><td>Tema resmi bawaan, fitur lengkap</td></tr><tr><td><code>emerald</code></td><td>Minimalis, modern, responsif</td></tr></tbody></table><h3 id="langkah" tabindex="-1">Langkah <a class="header-anchor" href="#langkah" aria-label="Permalink to &quot;Langkah&quot;">​</a></h3><ol><li>Pilih tema → <strong>Simpan</strong> (setting <code>active_theme</code> di tabel <code>settings</code>).</li><li>Lihat hasil di halaman publik. <strong>Tidak perlu</strong> mengubah kode atau build ulang.</li><li>Kembalikan ke <code>default</code> kapan saja bila ada masalah.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Dashboard admin <strong>tidak terpengaruh</strong> tema — hanya portal publik yang berubah. Detail teknis untuk pengembang: <a href="/panduan-pengembang/multi-tema.html">Sistem Multi-Tema</a>.</p></div><h2 id="pengaturan-situs-terkait" tabindex="-1">Pengaturan Situs Terkait <a class="header-anchor" href="#pengaturan-situs-terkait" aria-label="Permalink to &quot;Pengaturan Situs Terkait&quot;">​</a></h2><p>Identitas yang tampil di portal &amp; kop surat diatur di <strong>Pengaturan → Situs</strong>: nama desa, kode desa, kecamatan, kabupaten, provinsi, alamat, telepon, email, judul &amp; tagline situs, serta <strong>logo desa</strong> (dipakai pada PDF &amp; kop).</p>',14)])])}const g=t(d,[["render",r]]);export{h as __pageData,g as default};
